tools.schemaJson:
{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to read (relative or absolute). May end with a trailing selector such as :50-100 or :raw, address an archive member (archive.zip:inner/file), or address a SQLite database (data.db:table?limit=20)"
    },
    "offset": {
      "type": "integer",
      "description": "Line number to start reading from (1-indexed)"
    },
    "limit": {
      "type": "integer",
      "description": "Maximum number of lines to read"
    },
    "hashline": {
      "type": "boolean",
      "description": "Prefix each line with its line number and prepend a [path#TAG] content-hash header for anchoring hashline edit patches (default: false)"
    }
  },
  "required": [
    "path"
  ]
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to write (relative or absolute)"
    },
    "content": {
      "type": "string",
      "description": "Content to write to the file"
    }
  },
  "required": [
    "path",
    "content"
  ]
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to edit (relative or absolute). Required for exact-match mode; optional in hashline mode (the patch header carries its own [path#TAG])."
    },
    "oldText": {
      "type": "string",
      "description": "Exact-match mode: exact text to replace. Must occur exactly once in the file."
    },
    "newText": {
      "type": "string",
      "description": "Exact-match mode: replacement text (may be empty to delete oldText)."
    },
    "patch": {
      "type": "string",
      "description": "Hashline mode: a hashline patch — [path#TAG] section header(s) followed by SWAP/DEL/INS ops anchored on line numbers from a hashline-mode read."
    }
  }
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Directory to list (default: current directory)"
    },
    "limit": {
      "type": "integer",
      "description": "Maximum number of entries to return (default: 500)"
    }
  }
}

{
  "type": "object",
  "properties": {
    "command": {
      "type": "string",
      "description": "The bash command to execute"
    },
    "timeout": {
      "type": "number",
      "description": "Timeout in seconds (optional, no default timeout)"
    },
    "background": {
      "type": "boolean",
      "description": "Run detached and return the job id immediately (optional, default false). Use for long-running commands."
    },
    "stdin": {
      "type": "string",
      "description": "Optional text written to the command's stdin right after start (a password/passphrase the USER supplied via the ask tool, or \"y\\n\"). Use when the command prompts for input, e.g. ssh-add or sudo. Never invent secrets — ask first."
    }
  },
  "required": [
    "command"
  ]
}

{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "status",
        "output",
        "stop"
      ],
      "description": "What to do with the job(s)"
    },
    "id": {
      "type": "string",
      "description": "The job id (e.g. sh-1); required for output/stop"
    },
    "lines": {
      "type": "number",
      "description": "Log tail size for output (default 50)"
    },
    "all": {
      "type": "boolean",
      "description": "status without id: list every exited job too"
    }
  },
  "required": [
    "action"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "diagnostics",
        "definition",
        "references",
        "rename"
      ],
      "description": "The language-server operation to run"
    },
    "path": {
      "type": "string",
      "description": "File to inspect (relative or absolute). For rename, the file containing the symbol"
    },
    "line": {
      "type": "integer",
      "description": "1-indexed line of the symbol (default 1); used by definition/references/rename"
    },
    "character": {
      "type": "integer",
      "description": "1-indexed character (column) of the symbol (default 1); used by definition/references/rename"
    },
    "newName": {
      "type": "string",
      "description": "The new identifier (required for rename)"
    }
  },
  "required": [
    "op",
    "path"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The search query"
    },
    "count": {
      "type": "integer",
      "description": "Maximum number of results to return (default: 10, max: 20)"
    },
    "site": {
      "type": "string",
      "description": "Restrict results to a single domain, e.g. 'pub.dev' (appended as a site: filter)"
    }
  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "url": {
      "type": "string",
      "description": "The absolute http(s) URL to fetch"
    }
  },
  "required": [
    "url"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "check",
        "path",
        "get",
        "set"
      ],
      "description": "The config operation to run"
    },
    "key": {
      "type": "string",
      "description": "Dotted config key for get/set (memory.projectPath, tools.web_search, provider, ...)"
    },
    "value": {
      "type": "string",
      "description": "The new value for set, rendered as a yaml scalar: true/false verbatim, numbers verbatim, lists/maps as compact JSON, strings plain or quoted"
    },
    "scope": {
      "type": "string",
      "enum": [
        "global",
        "project"
      ],
      "description": "Write scope for set. Default resolves by key: memory/cube/tools -> the project file (created minimal when absent), everything else -> the user file"
    }
  },
  "required": [
    "op"
  ]
}

{
  "type": "object",
  "properties": {
    "text": {
      "type": "string",
