import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:crypto/crypto.dart' as crypto;
import 'package:flutter_agent_harness/src/cli/provider_export.dart';
import 'package:test/test.dart';

Uint8List _refPbkdf2(
  List<int> password,
  List<int> salt,
  int iterations,
  int dkLen,
) {
  final hmac = crypto.Hmac(crypto.sha256, password);
  final out = BytesBuilder(copy: false);
  var block = 1;
  while (out.length < dkLen) {
    var u = hmac
        .convert([...salt, block >> 24, block >> 16, block >> 8, block])
        .bytes;
    final t = List<int>.of(u);
    for (var i = 1; i < iterations; i++) {
      u = hmac.convert(u).bytes;
      for (var j = 0; j < t.length; j++) {
        t[j] ^= u[j];
      }
    }
    out.add(t);
    block++;
  }
  return Uint8List.fromList(out.toBytes()).sublist(0, dkLen);
}

List<int> _refKeystream(List<int> key, List<int> nonce, int length) {
  final hmac = crypto.Hmac(crypto.sha256, key);
  final out = BytesBuilder(copy: false);
  var counter = 0;
  while (out.length < length) {
    out.add(
      hmac
          .convert([
            ...nonce,
            counter & 0xff,
            (counter >> 8) & 0xff,
            (counter >> 16) & 0xff,
            (counter >> 24) & 0xff,
          ])
          .bytes,
    );
    counter++;
  }
  return out.toBytes();
}

String _refEncrypt(
  String plaintext,
  String passphrase, {
  required int iterations,
  required List<int> salt,
  required List<int> nonce,
}) {
  final plainBytes = utf8.encode(plaintext);
  final keys = _refPbkdf2(utf8.encode(passphrase), salt, iterations, 64);
  final encKey = keys.sublist(0, 32);
  final macKey = keys.sublist(32);
  final ks = _refKeystream(encKey, nonce, plainBytes.length);
  final ct = [for (var i = 0; i < plainBytes.length; i++) plainBytes[i] ^ ks[i]];
  final tag = crypto.Hmac(crypto.sha256, macKey).convert([...nonce, ...ct]);
  return base64Encode([...ct, ...tag]);
}

void main() {
  final rng = Random(42);
  Uint8List randBytes(int n) =>
      Uint8List.fromList(List.generate(n, (_) => rng.nextInt(256)));

  test('pbkdf2Sha256 differential vs package:crypto', () {
    for (var i = 0; i < 60; i++) {
      final pwLen = [0, 1, 32, 63, 64, 65, 100][rng.nextInt(7)];
      final saltLen = rng.nextInt(40);
      final iters = [1, 2, 3, 17, 100, 1000][rng.nextInt(6)];
      final dkLen = 1 + rng.nextInt(100);
      final pw = randBytes(pwLen);
      final salt = randBytes(saltLen);
      expect(
        pbkdf2Sha256(pw, salt, iters, dkLen).toList(),
        _refPbkdf2(pw, salt, iters, dkLen).toList(),
        reason: 'pw=$pwLen salt=$saltLen iters=$iters dkLen=$dkLen',
      );
    }
  });

  test('full envelope differential vs package:crypto (32-byte edges)', () {
    for (final len in [0, 1, 31, 32, 33, 63, 64, 65, 100, 1000, 10000]) {
      final salt = randBytes(16);
      final nonce = randBytes(16);
      final pass = 'p' * (1 + rng.nextInt(90));
      final payload = utf8.decode(List.filled(len, 0x61));
      final ref = _refEncrypt(
        payload,
        pass,
        iterations: 1000,
        salt: salt,
        nonce: nonce,
      );
      final env = encryptProvidersExport(
        payload,
        pass,
        iterations: 1000,
        salt: salt,
        nonce: nonce,
      );
      expect(env['ct'], ref, reason: 'payload len=$len');
      // and the new impl decrypts the reference-produced blob
      expect(decryptProvidersExport(env, pass), payload);
    }
  });
}

